impl Locale{
 pub fn text<'a>(self,key:&'a str)->Cow<'a,str>{match self{Self::En=>Cow::Borrowed(match key{"capability.pending"=>"This host service is not connected yet.","projection.mismatch"=>"The document does not match the published frame.","draft.invalid"=>"Enter a finite number in the supported format.","draft.unpublished"=>"The change has not been published. Retry or cancel it.","input.busy"=>"Finish the previous edit first.","draft.stale"=>"The field source changed. Refresh or cancel the draft.","layout.invalid"=>"A layout needs one viewport and no duplicate panels.",_=>key}),Self::Ru=>STRINGS.iter().find(|(k,_)|*k==key).map_or(Cow::Borrowed(key),|(_,v)|Cow::Borrowed(*v))}}
 pub fn number(self,value:f64,precision:usize)->String{let mut s=format!("{value:.precision$}");if s.contains('.') {s=s.trim_end_matches('0').trim_end_matches('.').to_owned();}if self==Self::Ru{s=s.replace('.',",");}s}
 pub fn parse(self,text:&str)->Result<f64,String>{let s=if self==Self::Ru{text.trim().replace(',',".")}else{text.trim().to_owned()};let value=s.parse::<f64>().map_err(|_|"draft.invalid".to_owned())?;if value.is_finite(){Ok(value)}else{Err("draft.invalid".into())}}
}
